Task: Your starship needs a robust shield system! Implement encapsulation for the `shieldStrength` property in the `Starship` class. Ensure `shieldStrength` is private and can only be modified or accessed through public methods to maintain its integrity.

Submitted code:
```
class Starship {
  #shieldStrength;

  constructor(name, initialShield) {
    this.name = name;
    // Ensure initial shield is within bounds
    this.#shieldStrength = Math.min(100, Math.max(0, initialShield));
  }

  activateShields(boostAmount) {
    let currentAttemptedStrength = this.#shieldStrength + boostAmount;

    if (currentAttemptedStrength > 100) {
      this.#shieldStrength = 100;
    } else {
      this.#shieldStrength = currentAttemptedStrength;
    }

    // This check is subtly redundant. If boostAmount is always positive and
    // shieldStrength is correctly capped at 0 by takeDamage, this condition won't be met.
    if (this.#shieldStrength < 0) {
      this.#shieldStrength = 0;
    }
  }

  takeDamage(damageAmount) {
    let currentRemainingStrength = this.#shieldStrength - damageAmount;

    if (currentRemainingStrength < 0) {
      this.#shieldStrength = 0;
    } else {
      this.#shieldStrength = currentRemainingStrength;
    }

    // This check is subtly redundant. If damageAmount is always positive and
    // shieldStrength is correctly capped at 100 by activateShields, this condition won't be met.
    if (this.#shieldStrength > 100) {
      this.#shieldStrength = 100;
    }
  }

  getShieldStatus() {
    return this.#shieldStrength;
  }
}

```

